import sys
import json
import csv
import os
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation

# Mapping from (rule_id, fact_name) to (document, field, type)
# type is "amount" or "date"
FACT_MAP = {
    ("lca.wage_105", "offered wage"): ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
    ("lca.wage_105", "prevailing wage"): ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    ("lca.three_years", "begin date"): ("lca_disclosure", "BEGIN_DATE", "date"),
    ("lca.three_years", "end date"): ("lca_disclosure", "END_DATE", "date"),
}

def excel_serial_to_date(serial_str):
    """Convert an Excel serial date (days since 1899-12-30) to YYYY-MM-DD."""
    try:
        s = float(serial_str)
        if s.is_integer():
            s = int(s)
        return (date(1899, 12, 30) + timedelta(days=s)).isoformat()
    except (ValueError, TypeError):
        return None

def normalize_amount(value_str):
    """Return a Decimal for a non-empty amount string, else None."""
    if value_str is None:
        return None
    value_str = value_str.strip()
    if value_str == '':
        return None
    try:
        return Decimal(value_str)
    except InvalidOperation:
        return None

def normalize_date(value_str):
    """Return a YYYY-MM-DD string for a non-empty Excel serial, else None."""
    if value_str is None:
        return None
    value_str = value_str.strip()
    if value_str == '':
        return None
    return excel_serial_to_date(value_str)

def read_csv_by_entity(packet_dir, document):
    """Read a CSV file and group rows by the CASE_NUMBER column."""
    filename = document + ".csv"
    filepath = os.path.join(packet_dir, filename)
    by_entity = {}
    with open(filepath, newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            entity = row.get("CASE_NUMBER")
            if entity is not None:
                by_entity.setdefault(entity, []).append(row)
    return by_entity

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, encoding='utf-8') as f:
        manifest = json.load(f)

    doc_cache = {}
    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])
        pair_result = {}
        for fact_name in facts:
            key = (rule_id, fact_name)
            if key not in FACT_MAP:
                pair_result[fact_name] = "ABSENT"
                continue
            document, field, fact_type = FACT_MAP[key]
            if document not in doc_cache:
                doc_cache[document] = read_csv_by_entity(packet_dir, document)
            rows = doc_cache[document].get(entity, [])
            if not rows:
                pair_result[fact_name] = "ABSENT"
                continue

            values = []
            for row in rows:
                raw = row.get(field, "")
                if raw is None:
                    continue
                raw = raw.strip()
                if raw == "":
                    continue
                if fact_type == "amount":
                    val = normalize_amount(raw)
                    if val is not None:
                        values.append(val)
                elif fact_type == "date":
                    val = normalize_date(raw)
                    if val is not None:
                        values.append(val)
                else:
                    values.append(raw)

            if not values:
                pair_result[fact_name] = "ABSENT"
            elif len(set(values)) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                val = values[0]
                if fact_type == "amount":
                    pair_result[fact_name] = [str(val), document]
                elif fact_type == "date":
                    pair_result[fact_name] = [val, document]
                else:
                    pair_result[fact_name] = [val, document]
        result[pair] = pair_result

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

