import sys
import os
import json
import csv
from datetime import datetime, timedelta
from decimal import Decimal

# Mapping from (rule_id, fact_name) to CSV column name
RULE_FACT_COLUMN = {
    "lca.wage_105": {
        "offered wage": "WAGE_RATE_OF_PAY_FROM",
        "prevailing wage": "PREVAILING_WAGE",
    },
    "lca.three_years": {
        "begin date": "BEGIN_DATE",
        "end date": "END_DATE",
    },
}

def excel_serial_to_date(s):
    """Convert Excel serial date string to YYYY-MM-DD."""
    try:
        d = Decimal(s)
        days = int(d)  # truncate fractional part (time) for date
        base = datetime(1899, 12, 30)
        dt = base + timedelta(days=days)
        return dt.date().isoformat()
    except Exception:
        return None

def extract_fact(entity_data, col, is_date):
    """Extract a fact from the collected rows for one entity."""
    values = entity_data.get(col, [])
    non_empty = [v for v in values if v != '']
    if not non_empty:
        return "ABSENT"

    if is_date:
        parsed = []
        for v in non_empty:
            d = excel_serial_to_date(v)
            if d is not None:
                parsed.append(d)
        if not parsed:
            return "ABSENT"
        if len(set(parsed)) == 1:
            return [parsed[0], "lca_disclosure"]
        return "CONFLICT"
    else:
        parsed = []
        for v in non_empty:
            try:
                parsed.append(Decimal(v))
            except Exception:
                pass
        if not parsed:
            return "ABSENT"
        if len(set(parsed)) == 1:
            return [non_empty[0], "lca_disclosure"]
        return "CONFLICT"

def load_data(packet_dir):
    """Load the lca_disclosure.csv file and group rows by CASE_NUMBER."""
    data = {}
    filepath = os.path.join(packet_dir, "lca_disclosure.csv")
    if not os.path.exists(filepath):
        return data
    with open(filepath, newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            # Strip whitespace from keys and values
            row = {k.strip(): (v.strip() if v is not None else '') for k, v in row.items()}
            case = row.get('CASE_NUMBER', '')
            if not case:
                continue
            if case not in data:
                data[case] = {}
            for col in ['WAGE_RATE_OF_PAY_FROM', 'PREVAILING_WAGE', 'BEGIN_DATE', 'END_DATE']:
                val = row.get(col, '')
                if col not in data[case]:
                    data[case][col] = []
                data[case][col].append(val)
    return data

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]
    with open(manifest_path, encoding='utf-8') as f:
        manifest = json.load(f)
    data = load_data(packet_dir)
    output = {}
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::')
        facts = manifest['facts'].get(rule_id, [])
        result = {}
        for fact in facts:
            col = RULE_FACT_COLUMN.get(rule_id, {}).get(fact)
            if col is None:
                result[fact] = "ABSENT"
                continue
            is_date = col in ('BEGIN_DATE', 'END_DATE')
            if entity not in data:
                result[fact] = "ABSENT"
            else:
                result[fact] = extract_fact(data[entity], col, is_date)
        output[pair] = result
    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

