import csv
import json
import os
import sys
from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation

def excel_serial_to_date(serial):
    base = datetime(1899, 12, 30)
    return base + timedelta(days=int(serial))

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, encoding='utf-8-sig') as f:
        manifest = json.load(f)

    pairs = manifest['pairs']
    facts_by_rule = manifest['facts']

    field_map = {
        ('lca.wage_105', 'offered wage'): ('WAGE_RATE_OF_PAY_FROM', 'amount'),
        ('lca.wage_105', 'prevailing wage'): ('PREVAILING_WAGE', 'amount'),
        ('lca.three_years', 'begin date'): ('BEGIN_DATE', 'date'),
        ('lca.three_years', 'end date'): ('END_DATE', 'date'),
    }

    csv_path = os.path.join(packet_dir, 'lca_disclosure.csv')
    by_case = {}
    with open(csv_path, newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            case = row['CASE_NUMBER']
            by_case.setdefault(case, []).append(row)

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split('::', 1)
        fact_names = facts_by_rule[rule_id]
        rows = by_case.get(entity, [])

        fact_result = {}
        for fact_name in fact_names:
            mapping = field_map.get((rule_id, fact_name))
            if mapping is None:
                fact_result[fact_name] = 'ABSENT'
                continue

            field, dtype = mapping
            values = []
            for row in rows:
                val = row.get(field, '').strip()
                if val == '':
                    continue
                try:
                    if dtype == 'date':
                        dt = excel_serial_to_date(float(val))
                        values.append(dt.strftime('%Y-%m-%d'))
                    elif dtype == 'amount':
                        values.append(str(Decimal(val)))
                except (ValueError, InvalidOperation, OverflowError):
                    continue

            if len(values) == 0:
                fact_result[fact_name] = 'ABSENT'
            else:
                unique = list(dict.fromkeys(values))
                if len(unique) == 1:
                    fact_result[fact_name] = [unique[0], 'lca_disclosure']
                else:
                    fact_result[fact_name] = 'CONFLICT'

        result[pair] = fact_result

    print(json.dumps(result, indent=2))

main()

